import { Component, ChangeDetectionStrategy, EventEmitter, Input, Output, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { ContactService } from '../../services/contact.service';
import { ToastService } from '../../services/toast.service';
import { IconComponent } from '../../components/ui/icon/icon.component';
import { Contact } from '../../models/contact.model';
import { BehaviorSubject, combineLatest, Observable, Subscription } from 'rxjs';
import { map } from 'rxjs/operators';
import { AddressInputQrComponent } from '../../components/ui/address-input-qr/address-input-qr.component';
import { ContactFormModalComponent } from '../contact-form-modal/contact-form-modal.component';

@Component({
    selector: 'app-contact-select-modal',
    standalone: true,
    imports: [CommonModule, FormsModule, TranslateModule, IconComponent, AddressInputQrComponent, ContactFormModalComponent],
    templateUrl: './contact-select-modal.component.html',
    styleUrls: ['./contact-select-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush
})
export class ContactSelectModalComponent implements OnInit, OnDestroy {
    @Input() isOpen = false;
    @Input() initialAddress = '';
    @Output() close = new EventEmitter<void>();
    @Output() selectAddress = new EventEmitter<string>();

    searchQuery$ = new BehaviorSubject<string>('');
    contacts$ = this.contactService.contacts$;
    filteredContacts$: Observable<Contact[]>;

    inputAddress = '';
    showCreateModal = false;

    private sub!: Subscription;

    constructor(
        private contactService: ContactService,
        private toastService: ToastService
    ) {
        this.filteredContacts$ = combineLatest([
            this.contacts$,
            this.searchQuery$
        ]).pipe(
            map(([contacts, query]) => {
                if (!query) return contacts;
                const q = query.toLowerCase();
                return contacts.filter(c =>
                    c.address.toLowerCase().includes(q) ||
                    (c.label && c.label.toLowerCase().includes(q))
                );
            })
        );
    }

    ngOnInit() {
        this.inputAddress = this.initialAddress;
    }

    ngOnDestroy() {
        if (this.sub) {
            this.sub.unsubscribe();
        }
    }

    onSearchChange(query: string) {
        this.searchQuery$.next(query);
    }

    onRowClick(address: string) {
        this.selectAddress.emit(address);
        this.closeModal();
    }

    onCloseClick() {
        this.closeModal();
    }

    closeModal() {
        this.isOpen = false;
        this.searchQuery$.next('');
        this.inputAddress = '';
        this.close.emit();
    }

    openCreateContactModal() {
        this.showCreateModal = true;
    }

    handleSaveNewContact(contact: { address: string, label: string }) {
        this.contactService.addContact({
            address: contact.address.trim(),
            label: contact.label.trim()
        });
        this.toastService.success('CONTACTS.UPDATED_SUCCESS');

        this.selectAddress.emit(contact.address.trim());
        this.showCreateModal = false;
        this.closeModal();
    }


    deleteContact(address: string, event: Event) {
        event.stopPropagation();
        if (confirm('Are you sure you want to delete this contact?')) {
            this.contactService.removeContact(address);
            this.toastService.success('CONTACTS.DELETED_SUCCESS');
        }
    }
}
