import { Component, forwardRef, Input, OnInit, OnDestroy } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ToastService } from '@services/toast.service';
import { IconComponent } from '../icon/icon.component';
import { LoggerService } from "@services/logger.service";
import { ContactSelectModalComponent } from '../../../modals/contact-select-modal/contact-select-modal.component';
import { QrScannerComponent } from '../qr-scanner/qr-scanner.component';
import { ContactService } from '@services/contact.service';
import { Subscription } from 'rxjs';

@Component({
    selector: 'app-contact-input',
    standalone: true,
    imports: [CommonModule, FormsModule, IconComponent, ContactSelectModalComponent, QrScannerComponent],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => ContactInputComponent),
            multi: true
        }
    ],
    templateUrl: './contact-input.component.html',
    styleUrls: ['./contact-input.component.css']
})
export class ContactInputComponent implements ControlValueAccessor, OnInit, OnDestroy {
    @Input() placeholder = '0x...';
    @Input() label = '';
    @Input() disabled = false;

    address = '';
    showModal = false;
    showDirectScanner = false;
    displayValue = '';

    private contactsSub!: Subscription;
    private contactsMapping: { [address: string]: string } = {};

    private onChange: (value: string) => void = () => { };
    private onTouched: () => void = () => { };

    constructor(
        private toastService: ToastService,
        private logger: LoggerService,
        private contactService: ContactService
    ) { }

    ngOnInit(): void {
        this.logger.debug('[AddressInputQrComponent] initialized');
        this.contactsSub = this.contactService.contacts$.subscribe(contacts => {
            this.contactsMapping = {};
            contacts.forEach(c => {
                this.contactsMapping[c.address.toLowerCase()] = c.label || 'Contact';
            });
            this.updateDisplayValue();
        });
    }

    ngOnDestroy(): void {
        this.logger.debug('[AddressInputQrComponent] destroyed');
        if (this.contactsSub) {
            this.contactsSub.unsubscribe();
        }
    }

    writeValue(value: string): void {
        this.address = value || '';
        this.updateDisplayValue();
    }

    registerOnChange(fn: (value: string) => void): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: () => void): void {
        this.onTouched = fn;
    }

    private updateDisplayValue() {
        if (!this.address) {
            this.displayValue = '';
            return;
        }
        const label = this.contactsMapping[this.address.toLowerCase()];
        if (label) {
            this.displayValue = `${label} (${this.address.substring(0, 6)}...${this.address.substring(38)})`;
        } else {
            this.displayValue = this.address;
        }
    }

    openModal() {
        if (!this.disabled) {
            this.showModal = true;
            this.onTouched(); // mark as touched when opened
        }
    }

    closeModal() {
        this.showModal = false;
    }

    handleAddressSelected(selectedAddress: string) {
        this.address = selectedAddress;
        this.updateDisplayValue();
        this.onChange(this.address);
        this.onTouched();
    }

    openScannerDirectly(event: Event) {
        event.stopPropagation();
        if (!this.disabled) {
            this.showDirectScanner = true;
            this.onTouched();
        }
    }

    closeDirectScanner() {
        this.showDirectScanner = false;
    }

    handleDirectScan(scannedAddress: string) {
        this.address = scannedAddress;
        this.updateDisplayValue();
        this.onChange(this.address);
        this.onTouched();
        this.closeDirectScanner();
        this.toastService.success('Address scanned successfully!');
    }

    async copyAddress(event: Event) {
        event.stopPropagation();
        if (!this.address) return;

        try {
            await navigator.clipboard.writeText(this.address);
            this.toastService.success('Address copied!');
        } catch (e) {
            this.logger.error('Failed to copy', e);
            this.toastService.error('Failed to copy address');
        }
    }
}
